/// Exact canonical dispatcher for `Quantity` validation.
fn validate_quantity_exact(
    valueset_url: &str,
    quantity: &Quantity,
) -> Result<(), TerminologyValidationError> {
    let code = quantity
        .code
        .as_ref()
        .and_then(|e| e.value.as_deref())
        .filter(|v| !v.is_empty())
        .ok_or_else(|| {
            TerminologyValidationError::InvalidInput("Quantity.code is required".to_string())
        })?;
    validate_code_exact(valueset_url, code)
}

/// Validate a system+code pair against a generated local ValueSet when available.
/// Falls back from versioned canonical URLs to the base canonical URL.
pub fn validate_code(valueset_url: &str, code: &str) -> Result<(), TerminologyValidationError> {
    match validate_code_exact(valueset_url, code) {
        Ok(()) => Ok(()),
        Err(TerminologyValidationError::RemoteValidationRequired(_)) => {
            if let Some((base, _version)) = valueset_url.split_once('|') {
                validate_code_exact(base, code)
            } else {
                Err(TerminologyValidationError::RemoteValidationRequired(
                    format!(
                        "Remote terminology validation required for {}",
                        valueset_url
                    ),
                ))
            }
        }
        Err(err) => Err(err),
    }
}

